    def find_pitch(length, horizontal):
        # The first tile begins at index 1. Its frame-color run determines
        # the tile width/height; the next tile start gives the pitch.
        vals = [grid[1][i] if horizontal else grid[i][1]
                for i in range(length)]
        run = 0
        for v in vals[1:]:
            if v != frame:
                break
            run += 1
        for p in range(run + 1, min(length, run + 10)):
            if 1 + p < length and vals[1 + p] == frame:
                return p, run
        return run + 2, run

    pc, tile_w = find_pitch(w, True)
    pr, tile_h = find_pitch(h, False)
